package in.aitechapp.telugumatalu;
import java.util.*;import java.util.regex.*;import java.text.Normalizer;
public final class Transliterator {
 private static final Map<Character,String> C=new HashMap<>(),V=new HashMap<>(),S=new HashMap<>();
 static{put(C,"క:k ఖ:kh గ:g ఘ:gh ఙ:ng చ:ch ఛ:chh జ:j ఝ:jh ఞ:ny ట:t ఠ:th డ:d ఢ:dh ణ:n త:t థ:th ద:d ధ:dh న:n ప:p ఫ:ph బ:b భ:bh మ:m య:y ర:r ఱ:r ల:l ళ:l వ:v శ:sh ష:sh స:s హ:h ఴ:zh ౘ:ts ౙ:dz ౚ:rr");put(V,"అ:a ఆ:aa ఇ:i ఈ:ee ఉ:u ఊ:oo ఋ:ru ౠ:roo ఌ:lu ౡ:loo ఎ:e ఏ:e ఐ:ai ఒ:o ఓ:o ఔ:au");put(S,"ా:aa ి:i ీ:ee ు:u ూ:oo ృ:ru ౄ:roo ె:e ే:e ై:ai ొ:o ో:o ౌ:au ౢ:lu ౣ:loo");}
 private static void put(Map<Character,String>m,String data){for(String p:data.split(" ")){String[]a=p.split(":");m.put(a[0].charAt(0),a[1]);}}
 public final Map<String,String> words,custom=new LinkedHashMap<>();public boolean natural=true,capital=true;
 public Transliterator(Map<String,String> words){this.words=words;}
 public String raw(String text){StringBuilder b=new StringBuilder();for(int i=0;i<text.length();i++){char c=text.charAt(i);if(C.containsKey(c)){b.append(C.get(c));int j=i+1;while(j<text.length()&&(text.charAt(j)=='\u200d'||text.charAt(j)=='\u200c'))j++;char next=j<text.length()?text.charAt(j):0;if(next=='్')i=j;else if(S.containsKey(next)){b.append(S.get(next));i=j;}else b.append('a');}else if(V.containsKey(c))b.append(V.get(c));else if(c=='ం'||c=='ఁ'||c=='ఀ'||c=='ఄ'){char n=i+1<text.length()?text.charAt(i+1):0;b.append(n!=0&&"కఖగఘఙచఛజఝఞటఠడఢణతథదధన".indexOf(n)>=0?'n':'m');}else if(c=='ః')b.append('h');else if(c>='౦'&&c<='౯')b.append(c-'౦');else if(c=='్'||c=='\u200d'||c=='\u200c'||c=='఼'){}else if(S.containsKey(c))b.append(S.get(c));else b.append(c);}return b.toString();}
 public String convert(String text){text=Normalizer.normalize(text,Normalizer.Form.NFC);Matcher m=Pattern.compile("[\\u0c00-\\u0c7f][\\u0c00-\\u0c7f\\u200c\\u200d]*").matcher(text);StringBuffer out=new StringBuffer();while(m.find()){String w=m.group(),r=custom.containsKey(w)?custom.get(w):natural&&words.containsKey(w)?words.get(w):raw(w);m.appendReplacement(out,Matcher.quoteReplacement(r));}m.appendTail(out);if(!capital)return out.toString();Matcher caps=Pattern.compile("(^|[.!?\\n]\\s*)([a-z])").matcher(out.toString());StringBuffer b=new StringBuffer();while(caps.find())caps.appendReplacement(b,Matcher.quoteReplacement(caps.group(1)+caps.group(2).toUpperCase(Locale.ROOT)));caps.appendTail(b);return b.toString();}
 public static final class Token{public int start,end,outStart,outEnd;public Token(int s,int e,int os,int oe){start=s;end=e;outStart=os;outEnd=oe;}}
 public List<Token> align(String text){List<Token>p=new ArrayList<>();Matcher m=Pattern.compile("\\s+|\\S+").matcher(text);int o=0;while(m.find()){int length=convert(m.group()).length();if(!m.group().trim().isEmpty())p.add(new Token(m.start(),m.end(),o,o+length));o+=length;}return p;}
 public static List<int[]> chunks(String s){List<int[]>list=new ArrayList<>();Matcher m=Pattern.compile("\\S+").matcher(s);int start=-1,end=0;while(m.find()){if(start<0)start=m.start();if(m.end()-start>180&&end>start){list.add(new int[]{start,end});start=m.start();}end=m.end();if(m.group().matches(".*[.!?।॥]$")||(end<s.length()&&s.charAt(end)=='\n')){list.add(new int[]{start,end});start=-1;}}if(start>=0)list.add(new int[]{start,end});return list;}
}
